NEED_RE = {k: re.compile(v, I) for k, v in NEEDS.items()}


def classify_return(text):
    """Return (class, subtype, prior_repeat_flag). Order: explicit non-return -> explicit return -> behavioural signal -> insufficient."""
    non = NON_RETURN.search(text)
    rep = RET_REPORTED.search(text)
    intent = RET_INTENT.search(text)
    if non:
        return "Explicit Non-Return", "previously a repeat customer" if rep else "stated will not return / switched / uninstalled", bool(rep)
    if rep:
        return "Explicit Return", "reports repeat or ongoing use", False
    if intent:
        return "Explicit Return", "states intent to book again", False
    wc = len(re.findall(r"\w+", text))
    if wc >= 8 and SIGNAL_TRUST.search(text):
        return "Behavioural Signal", "satisfaction / dissatisfaction / trust / switching cue", False
    return "Insufficient Evidence", "no repeat or non-return information", False
